  const candidates=catalog.filter(owner=>owner.id===(saved.owner||m.id)||owner.catalogFamily?.key&&owner.catalogFamily.key===m.catalogFamily?.key&&owner.cat===m.cat).flatMap(owner=>(owner.catalogSheets||[]).flatMap(sheet=>sheet.options||[]));
