function project(){return consultationDraft||state.projects.find(p=>p.id===state.active)}
async function initDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('yuhiha-material-review-only',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function readDB(){return new Promise((resolve,reject)=>{const r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function save(){const snapshot=structuredClone(state);setSaveStatus('저장 중…');saveChain=saveChain.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(!db){reject(Error('Storage unavailable'));return}const tx=db.transaction('data','readwrite');tx.objectStore('data').put(snapshot,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})).then(()=>{setSaveStatus('● 이 기기에 저장됨')}).catch(()=>{setSaveStatus('저장 실패 · 백업 필요');toast('브라우저 저장 공간을 확인해 주세요. 백업으로 현재 자료를 보관할 수 있습니다.')});return saveChain}
function subcategoryLabel(groupName, category) {
  if (category === '전체') return category;
  if (groupName === '벽지') return category + ' 벽지';
  if (groupName === '바닥재') {
    if (category.startsWith('마루 ')) return category.slice(3) + ' 마루';
    if (category.startsWith('장판 ')) return category.slice(3) + ' 장판';
  }
  return category;
}
function renderGroups(){if($('categoryNumber'))$('categoryNumber').textContent=group<0?'ALL':String(group+1).padStart(2,'0');$('groups').innerHTML=`<button class="${group<0?'active':''}" data-group="-1" aria-pressed="${group<0}"><span class="group-no">ALL</span>전체</button>`+GROUPS.map((g,i)=>`<button class="${group===i?'active':''}" data-group="${i}" aria-pressed="${group===i}"><span class="group-no">0${i+1}</span>${g.name}</button>`).join('');$('subcats').hidden=group<0;$('subcats').innerHTML=(group<0?[]:['전체',...GROUPS[group].cats.filter(c=>!(GROUPS[group].name==='욕실'&&c==='줄눈'))]).map(c=>`<button class="${subcategory===c?'active':''}" data-cat="${c}" aria-pressed="${subcategory===c}">${subcategoryLabel(GROUPS[group].name,c)}</button>`).join('');renderBrandChips();renderTileGroutPalette()}

function renderTileGroutPalette(){
  const panel = $('tileGroutPalette');
  const grout = GROUPS[group]?.name === '타일' && state.materials.find(m =>
    m.cat === '줄눈' && /아덱스|ardex/i.test([m.brand,m.name].join(' ')) &&
    /FG\s*4/i.test([m.name,m.productName,m.model].join(' ')) && Object.keys(m.colorImages || {}).length);
  panel.hidden = !grout;
  if (!grout) { panel.innerHTML = ''; return; }
  panel.innerHTML = '<strong>아덱스 FG4 줄눈</strong><div>' + Object.entries(grout.colorImages).map(([color,src]) =>
    `<button type="button" data-ardex-material="${escapeHTML(grout.id)}" data-shade="${escapeHTML(color)}"><img src="${escapeHTML(src)}" alt="">${escapeHTML(color)}</button>`
  ).join('') + '</div>';
}
const BRAND_SERIES={'벽지|LX Z:IN':['디아망','베스트']};
const BRAND_ALIASES={'대림':'대림바스','대림바스':'대림바스','백조':'백조씽크','백조씽크':'백조씽크','르그랑legrand':'르그랑','르그랑':'르그랑'};
function canonicalBrand(value){const name=String(value||'').trim();return BRAND_ALIASES[name.toLowerCase().replace(/\s+/g,'')]||name}
// Presentation only: preserve manufacturer SKU and measurement precision in source data.
function displayModel(m){
 if(TILE_CATALOG_CATEGORIES.has(m.cat))return tileCatalogName(m);
 let value=String(m.model||'').trim();
 if(['비반트','폰타나','에떼르노','아메리칸스탠다드','제이리빙','도무스','필로토'].includes(m.brand))
  value=value.replace(/\s*[·/]\s*(?:메트실버|메트그레이|사틴 헤어라인|브러쉬드 니켈|브러시드 니켈|니켈|화이트|크롬|블랙|골드)\s*$/,'');
 if(m.brand==='비반트')value=value.replace(/\((?:MS|MW|MG|CG|CB|CR)\)\s*$/,'').replace(/\s+(?:MS|MW|MG|CG|CB|CR)$/,'');
 if(m.brand==='폰타나'&&/^TF-AC7100B\s+BN$/.test(value))value='TF-AC7100B';
 if(m.brand==='필로토'&&value==='빅토리아샤워301 니켈')value='빅토리아샤워301';
 return value;
}
function displayBrandName(m){const brand=canonicalBrand(m.brand);return brand==='대림바스'?'대림':brand}
function standardDimensionText(value){
 if(String(value||'').trim()==='폭 1,220 mm × 길이 25 m')return '폭 1,220 mm × 길이 25 m';
 let text=String(value||'').trim();if(!text||/^(?:규격|치수|색상 정보).*?(?:확인 중|미입력)$/.test(text))return '';
 // Convert length units before rounding; never round 15.6 metres to 16 metres.
 text=text.replace(/(\d+(?:\.\d+)?)\s*(cm|m)(?=\s*(?:\([WDLHT]\)|[×xX/]|$))/g,(_,n,u)=>String(Number(n)*(u==='cm'?10:1000)));
 text=text.replace(/(\d+(?:\.\d+)?)\s*\(([WDLHT])\)/g,'$2 $1').replace(/\b([WDLHT])\s*(?=\d)/g,'$1 ')
 .replace(/\s*[×xX]\s*(?=\d|[WDLHT]\s*\d)/g,' × ').replace(/\s*\/\s*/g,' / ').replace(/\s*mm\b/g,'').replace(/[ØΦøφ]\s*(?=\d)/g,'Ø ');
 text=text.replace(/(\d+(?:\.\d+)?)\s*×\s*(\d+(?:\.\d+)?)\s*×\s*(\d+(?:\.\d+)?)\s*\(폭×길이×두께\)/g,'W $1 × L $2 × T $3');
 return integerDimensionText(text).replace(/ +/g,' ').trim();
}
function isCatalogFilm(m){return /필름/.test(m.cat||'') || GROUPS.some(g=>g.name==='필름' && g.cats.includes(m.cat))}
function filmProductName(m){
  const brand=canonicalBrand(m.brand), prefix=brand+'_';
  const name=String(m.name||'').trim(), model=String(m.model||'').trim();
  const unbrand=value=>brand==='한솔'?value.replace(/^한솔[\s_]+/,''):value.startsWith(prefix)?value.slice(prefix.length).trim():value;
  const product=unbrand(String(m.productName||'').trim());
  if(brand==='한솔' && [product,name,model].some(value=>value.includes('스토리보드'))){
    const finish=value=>value.replace(/^한솔[\s_]*/, '').replace(/스토리보드/g,'').replace(/_+/g,' ').trim();
    return finish(product)||finish(model)||finish(name);
  }
  if(product && product!==model)return product;
  const saved=String(m.originalName||'').trim();
  const full=saved.startsWith(name+'_') && name!==prefix+model ? saved : name;
  const label=unbrand(full).replace(/_+/g,' ').trim();
  return label && label!==model ? label : '';
}
const TILE_CATALOG_CATEGORIES = new Set(['300×300','300×600','600×600','600×1200','800×800','900×900','기타 규격']);
const TILE_SIZE = /(\d+(?:\.\d+)?)\s*[×xX＊*]\s*(\d+(?:\.\d+)?)/;
const TILE_SIZE_SUFFIX = /\s*\(\s*\d+(?:\.\d+)?\s*[×xX＊*]\s*\d+(?:\.\d+)?\s*(?:mm)?\s*\)\s*$/i;
function tileSupplier(m){
  let host;
  try { host=new URL(m.url).hostname.replace(/^www\./,''); } catch { return ''; }
  return ({'usong.co.kr':'유송타일','younhyunmall.com':'윤현상재','xn--2j1bq9j0vioncw7blzb1x0d.com':'아름다운화장실'})[host] || '';
}
function tileCatalogName(m){
  const original=String(m.name||'').trim();
  const brandPrefix=m.brand?m.brand+'_':'';
  let model=String(m.model||'').trim()||original;
  if(brandPrefix&&model.startsWith(brandPrefix))model=model.slice(brandPrefix.length);
  model=model.replace(TILE_SIZE_SUFFIX,'').trim();
  // Imported bilingual model names sometimes put a series code before the Korean alias.
  const parts=model.split(/\s+\/\s+/);
  if(parts.length===2){
    const [first,second]=parts;
    if(!/[가-힣]/.test(first)&&(/[가-힣]/.test(second)||(/\d/.test(first)&&/^[A-Z][A-Z -]+$/i.test(second))))model=first;
    else if(/[가-힣]/.test(first)&&!/[가-힣]/.test(second)){
      const series=first.match(/^([A-Z0-9-]+)\s+[가-힣]/)?.[1];
      model=series&&!second.startsWith(series+' ')?series+' '+second:second;
    }
  }
  if(!model)return original;
  return model.replace(/^([A-Z]+-\d+[A-Z]*)\s*\([^)]+\)$/, '$1');
}
function normalizeMaterialName(m){
  if(TILE_CATALOG_CATEGORIES.has(m.cat)){
    const next=tileCatalogName(m);
    if(next!==m.name){if(!m.originalName)m.originalName=m.name;m.name=next}
    return m;
  }
  if(isCatalogFilm(m)){
    const brand=canonicalBrand(m.brand), product=filmProductName(m);
    const value=product||String(m.model||'').trim();
    if(!value)return m;
    const next=brand?brand+(brand==='한솔'?' ':'_')+value:value;
    if(product)m.productName=product;
    if(next!==m.name){if(!m.originalName)m.originalName=m.name;m.name=next}
    return m;
  }
  const brand=canonicalBrand(m.brand),displayBrand=brand==='대림바스'?'대림':brand;
  if(!displayBrand)return m;
  const original=String(m.name||'').trim();
  const aliases=[brand,displayBrand,...Object.keys(BRAND_ALIASES).filter(k=>BRAND_ALIASES[k]===brand)];
  if(brand==='LX Z:IN')aliases.push('LX');
  if(brand==='아메리칸스탠다드')aliases.push('아메스','American Standard');
  let product=original;
  for(const prefix of aliases.sort((a,b)=>b.length-a.length)){
    if(product.toLowerCase().startsWith(prefix.toLowerCase())&&/^[\s_*]/.test(product.slice(prefix.length))){product=product.slice(prefix.length).replace(/^[\s_*]+/,'');break}
  }
  const model=displayModel(m);
  if(m.brand==='비반트')product=product.replace(/\s+(?:MS|MW|MG|CG|CB|CR)(?=\s|$)/g,'');
  if(model&&product.toLowerCase().endsWith(model.toLowerCase())){
    const before=product.slice(0,-model.length);
    if(/[\s_*]$/.test(before)&&before.replace(/[\s_*]+$/,'').trim())product=before.replace(/[\s_*]+$/,'');
  }
  product=product.replace(/[_*]+/g,' ').replace(/\s+/g,' ').trim();
  const next=displayBrand+'_'+(product||model||original);
  if(next!==original){if(!m.originalName)m.originalName=original;m.name=next}
  return m;
}
function compareBrands(a,b){return canonicalBrand(a).localeCompare(canonicalBrand(b),'ko')}
function orderBrandsAlphabetically(items){
 const groups=new Map();for(const m of items){if(!groups.has(m.cat))groups.set(m.cat,[]);groups.get(m.cat).push(m)}
 for(const list of groups.values())list.sort((a,b)=>compareBrands(a.brand,b.brand));
 const positions=new Map();return items.map(m=>{const i=positions.get(m.cat)||0;positions.set(m.cat,i+1);return groups.get(m.cat)[i]});
}
function brandOf(m){if(TILE_CATALOG_CATEGORIES.has(m.cat)&&tileSupplier(m))return tileSupplier(m);return canonicalBrand(m.brand)||'브랜드 미입력'}
function brandActive(){return true}
// EXPLORE '전체' = group -1 (2026-11-25 사용자). 검색·브랜드 목록은 지금 고른 대분류 안에서만(전체면 모든 대분류).
function inGroup(m){if(m.cat==='줄눈'&&GROUPS[group]?.name==='욕실')return false;return group<0||!!GROUPS[group]?.cats.includes(m.cat)}
// 색 옵션 이름도 검색(2026-11-25: '273' 으로 아덱스 FG4 줄눈 찾기)
function matchesQuery(m){
  if(!query)return true;
  const tile=TILE_CATALOG_CATEGORIES.has(m.cat);
  const fields=[m.name,m.productName,m.brand,m.model,m.cat,m.spec,...Object.keys(m.colorImages||{})];
  if(tile)fields.push(m.originalName);
  const words=fields.join(' ').toLowerCase(),q=query.toLowerCase();
  return words.includes(q)||(tile&&fields.some(value=>String(value||'').toLowerCase().replace(/\s/g,'').includes(q.replace(/\s/g,''))));
}
function brandScope(m){return inGroup(m)&&(subcategory==='전체'||!!query||m.cat===subcategory)}
const RECESSED_TYPES=['다운라이트','실린더조명','사각매립등'];
function recessedType(m){
 const name=String(m.name||'').replace(/^.*?_/,'');
 if(/^(퍼민트|도티)(?:\s|$)/.test(name))return '실린더조명';
 if(/^(크리스타 MXF|사각 도트 MLD|티아노|크레드|예도)(?:\s|$)/.test(name))return '사각매립등';
 if(/^(안도|카멘|에코 카론)(?:\s|$)/.test(name))return '다운라이트';
 return '기타';
}
function seriesList(){if(subcategory==='매입등')return null;return brandActive()&&brand!=='전체'?BRAND_SERIES[subcategory+'|'+brand]||null:null}
function seriesOf(m,list){if(list===RECESSED_TYPES)return recessedType(m);return list.find(n=>String(m.name).includes(n))||'기타'}
function chipRow(label,key,current,entries){return `<span class="chip-label">${label}</span>`+entries.map(([n,c])=>`<button type="button" class="${current===n?'active':''}" data-${key}="${escapeHTML(n)}" aria-pressed="${current===n}">${escapeHTML(n)}<span class="chip-count">${c}</span></button>`).join('')}
function renderBrandChips(){
 const row=$('brandChips'),srow=$('seriesChips'),select=$('brandFilter');if(!select||!srow)return;
 if(row){row.hidden=true;row.innerHTML=''}
 const counts=new Map();for(const m of materials())if(GROUPS[group]?.name==='타일'?(inGroup(m)&&TILE_CATALOG_CATEGORIES.has(m.cat)):brandScope(m))counts.set(brandOf(m),(counts.get(brandOf(m))||0)+1);
 const names=[...counts.keys()].sort((a,b)=>compareBrands(a,b));
 if(brand!=='전체'&&!counts.has(brand))brand='전체';
 select.innerHTML='<option value="전체" hidden>브랜드</option><option value="전체">모든 브랜드</option>'+names.map(n=>`<option value="${escapeHTML(n)}">${escapeHTML(n)}</option>`).join('');select.value=brand;
 const sl=seriesList();if(!sl){series='전체';srow.hidden=true;srow.innerHTML='';return}
 const sc=new Map();for(const m of (sl===RECESSED_TYPES?groupElectricalCatalog(materials().filter(m=>brandScope(m)&&(brand==='전체'||brandOf(m)===brand))):materials().filter(m=>brandScope(m)&&brandOf(m)===brand))){const k=seriesOf(m,sl);sc.set(k,(sc.get(k)||0)+1)}
 const snames=[...sl,'기타'].filter(n=>sc.has(n));if(series!=='전체'&&!sc.has(series))series='전체';
 srow.hidden=false;srow.innerHTML=chipRow(sl===RECESSED_TYPES?'유형':'SERIES','series',series,[['전체',snames.reduce((t,n)=>t+sc.get(n),0)],...snames.map(n=>[n,sc.get(n)])])
}
