 const figure=button.closest('figure'),source=material(figure.dataset.electricalSource),srcOption=validElectricalOptions(source)[Number(figure.dataset.sourceOption)],b=srcOption.bounds,img=await imageOf(source.image),c=document.createElement('canvas');c.width=800;c.height=800;
