const floorPreviewCache = new Map();
document.addEventListener('load', event => {
  const img = event.target;
  if (!(img instanceof HTMLImageElement)) return;
  const host = img.closest('#catalog .material-image[data-detail]');
  if (!host || !flooringCatalogThumbnails.has(host.dataset.detail)) return;
  const source = material(host.dataset.detail)?.image;
  if (!source || img.getAttribute('src') !== source) return;
  let thumbnail = floorPreviewCache.get(source);
  if (!thumbnail) {
    const canvas = document.createElement('canvas');
    const scale = 296 / Math.max(img.naturalWidth, img.naturalHeight);
    canvas.width = Math.max(1, Math.round(img.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(img.naturalHeight * scale));
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    try { thumbnail = canvas.toDataURL('image/png'); } catch { return; }
    floorPreviewCache.set(source, thumbnail);
  }
  img.src = thumbnail;
}, true);
function catalogImageSource(m){
  if (flooringCatalogThumbnails.has(m.id)) return floorPreviewCache.get(m.image) || m.image;
  const src=m.cardImage||m.image;return staticTileCard(m)||readyTilePreviews.get(tilePreviewKey(src))||src;}
function tilePreviewPending(m){return !staticTileCard(m)&&needsTilePreview(m.cardImage||m.image)&&!readyTilePreviews.has(tilePreviewKey(m.cardImage||m.image))}
document.addEventListener('load', async event => {
  const img = event.target;
  if (!(img instanceof HTMLImageElement)) return;
  const src = img.currentSrc;
  const reveal=()=>{if(img.dataset.tilePreviewPending!==undefined){img.style.removeProperty("visibility");delete img.dataset.tilePreviewPending}};
  if(!needsTilePreview(src))return;
  if(img.naturalWidth!==1440||img.naturalHeight!==1440){reveal();return;}
  if (!fourRowPreviews.has(src)) {
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 1440;
    const ctx = canvas.getContext('2d');
    if(sidePaddedTileImages.has(src.slice(-64))){
      ctx.drawImage(img,180,0,1080,1440,0,0,1080,1440);
      ctx.drawImage(img,540,0,360,1440,1080,0,360,1440);
    }else{
      ctx.drawImage(img, 0, 180, 1440, 1080, 0, 0, 1440, 1080);
      ctx.drawImage(img, 0, 180, 1440, 360, 0, 1080, 1440, 360);
    }
    fourRowPreviews.set(src, new Promise(resolve => canvas.toBlob(blob => resolve(blob && URL.createObjectURL(blob)), 'image/png')));
  }
  const preview = await fourRowPreviews.get(src);
  if(preview)readyTilePreviews.set(tilePreviewKey(src),preview);
  if(img.currentSrc!==src||!img.isConnected)return;
  if(preview){const decoded=new Image();decoded.src=preview;try{await decoded.decode()}catch{}if(img.currentSrc!==src||!img.isConnected)return;img.src=preview;}
  reveal();
}, true);
let catalogMoreObserver;
function observeMoreMaterials(){
  catalogMoreObserver?.disconnect();
  if(typeof IntersectionObserver==='undefined')return;
  const button=$('catalog').querySelector('[data-catalog-more]');
  if(!button||typeof IntersectionObserver==='undefined')return;
  catalogMoreObserver=new IntersectionObserver(entries=>{
    if(entries.some(entry=>entry.isIntersecting)&&button.isConnected){
      catalogMoreObserver.disconnect();
      button.click();
    }
  });
  catalogMoreObserver.observe(button);
}
