// ---- 하트는 사람마다 따로(2026-11-25 사용자). 공용 자료의 state.favorites 는 화면에서 쓰지 않는다(옛 자료 호환용으로만 남김).
//  저장: 이 브라우저(localStorage) + 공용 서버가 있으면 로그인한 이메일별(/api/favorites). 처음 한 번은 예전 공용 하트를 내 하트로 가져온다.
const MY_FAV_KEY='yuhiha-my-favorites-v1',CATALOG_STEP=60;let myFavorites=[],myFavSaveTimer=0,catalogLimit=CATALOG_STEP,myFavBooted=false;
function isFav(id){return myFavorites.includes(id)}
function readMyFavLocal(){try{const v=JSON.parse(localStorage.getItem(MY_FAV_KEY)||'null');return Array.isArray(v)?v.filter(x=>typeof x==='string'):null}catch{return null}}
const favServer=()=>typeof fetch==='function'&&typeof location!=='undefined'&&/^https?:$/.test(location.protocol);
function saveMyFavorites(){try{localStorage.setItem(MY_FAV_KEY,JSON.stringify(myFavorites))}catch{}if(!favServer()||typeof setTimeout!=='function')return;clearTimeout(myFavSaveTimer);myFavSaveTimer=setTimeout(()=>{fetch('/api/favorites',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({favorites:myFavorites})}).catch(()=>{})},400)}
async function loadMyFavorites(){
 const local=readMyFavLocal();let remote;
 try{if(favServer()){const r=await fetch('/api/favorites');if(r.ok&&String(r.headers.get('content-type')).includes('json'))remote=(await r.json()).favorites}}catch{}
 myFavorites=(Array.isArray(remote)?remote:local??[...(state.favorites||[])]).filter(x=>typeof x==='string');
 if(!Array.isArray(remote)||local===null)saveMyFavorites();
 renderCatalog();
}
function resetMyFavorites(){if(!myFavorites.length)return toast('하트를 누른 자재가 없어요.');if(!confirm(`내가 하트를 누른 자재 ${myFavorites.length}개를 모두 해제할까요?\n다른 직원의 하트는 그대로예요.`))return;myFavorites=[];saveMyFavorites();renderCatalog();toast('하트를 모두 해제했어요.')}
function showFavorites(){updateCatalogView(()=>{filter=filter==='favorite'?'all':'favorite';$('catalogFilter').value=filter;group=-1;subcategory='전체';brand='전체';series='전체';query='';$('search').value='';renderGroups();renderCatalog()})}
// 목록 위 보조 줄: 다른 분류 검색 결과 안내 · 즐겨찾기 화면의 '하트 초기화' · 상단 메뉴 표시
