 const box=$('searchElsewhere');if(box){const more=query&&group>=0?materials().filter(m=>!inGroup(m)&&matchesQuery(m)&&(filter!=='favorite'||isFav(m.id))).length:0;box.hidden=!more;box.innerHTML=more?`다른 분류에 '${escapeHTML(query)}' 결과가 ${more}개 더 있어요 <button type="button" data-search-all>전체에서 보기 →</button>`:''}
