let approvedLightingDetailObserver;
function alignApprovedLightingDetail(m){
 approvedLightingDetailObserver?.disconnect();
 if(m?.approvalEvidence?.status!=='사용자 승인'||!['다운라이트','매입등','트림리스','마그네틱 조명','방등','온도조절기','분전반'].includes(m.cat))return;
 const img=$('detailContent').querySelector('.detail-image');if(!img)return;
 const align=()=>{if(!img.isConnected||!img.complete||!img.naturalWidth)return;const b=productVerticalBounds(img);if(!b)return;const r=img.getBoundingClientRect();const h=Math.min(r.width/img.naturalWidth,r.height/img.naturalHeight)*img.naturalHeight;const shift=(.5-(b.top+b.bottom)/2)*h;img.style.objectPosition=`50% calc(50% + ${shift.toFixed(3)}px)`};
 img.addEventListener('load',align);if(typeof ResizeObserver!=='undefined'){approvedLightingDetailObserver=new ResizeObserver(align);approvedLightingDetailObserver.observe(img)}align();
}
function detailSourceLabel(url){
 const catalog=String(url).match(/^https:\/\/www\.daelimbath\.com\/upload\/down\/[^?#]+\.pdf#page=(\d+)$/i);
 return catalog?'공식 카탈로그 '+catalog[1]+'쪽 ↗':'제품 상세 페이지 ↗';
}
let detailOpener=null;
function showMaterialDetail(){
 const dialog=$('detailDialog');
 if(!dialog.open){detailOpener=document.activeElement;dialog.showModal()}
 dialog.scrollTop=0;
 dialog.querySelector?.('.close')?.focus({preventScroll:true});
}
function closeMaterialDetail(){
 const dialog=$('detailDialog'),x=window.scrollX,y=window.scrollY;
 if(!dialog.open)return;
 dialog.close();
 // Remove old preview nodes immediately; their pending image callbacks must not
 // touch a subsequent product, even if it opens before the close event fires.
 $('detailContent').replaceChildren();
 if(detailOpener?.isConnected)detailOpener.focus({preventScroll:true});
 window.scrollTo({left:x,top:y,behavior:'instant'});
}
$('detailDialog').addEventListener('cancel',e=>{e.preventDefault();closeMaterialDetail()});
function bindFilmGallery(m){
  if (!isCatalogFilm(m) || !Array.isArray(m.applicationPhotos) || !m.applicationPhotos.length) return;
  const image = $('detailContent').querySelector('.detail-image');
  const photos = [m.image, ...m.applicationPhotos];
  const nav = document.createElement('nav');
  nav.className = 'lighting-option-nav';
  nav.setAttribute('aria-label','필름 사진 이동');
  nav.innerHTML = '<button type="button">← 이전</button><span aria-live="polite"></span><button type="button">다음 →</button>';
  image.after(nav);
  const [prev,next] = nav.querySelectorAll('button');
  let index = 0;
  function show(i){
    index = i;
    const label = i === 0 ? '재질 견본' : (m.applicationPhotoLabel || '적용 사례');
    image.src = photos[i];
    image.alt = m.name + ' · ' + label;
    nav.querySelector('span').textContent = label + ' ' + (i+1) + ' / ' + photos.length;
    prev.disabled = i === 0;
    next.disabled = i === photos.length-1;
  }
  prev.onclick = () => show(index-1);
  next.onclick = () => show(index+1);
  show(0);
}
